declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)$_SESSION['role'];if(!in_array($role,['admin','director','sub_director','headteacher','storekeeper'],true)){http_response_code(403);exit('Your role cannot access stocktakes.');}$db=db();$uid=(int)$_SESSION['user_id'];$q=$db->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();if(!$schools){http_response_code(403);exit('No school is linked to your account.');}$school=(int)($_GET['school_id']??$schools[0]['id']);if(!in_array($school,array_map('intval',array_column($schools,'id')),true)){http_response_code(403);exit('That school is outside your access.');}$manager=in_array($role,['admin','director','sub_director','headteacher'],true);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stocktakes · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/api.js"></script><script defer src="assets/stocktakes.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> Stores <span>/</span> Stocktakes</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e((string)($_SESSION['name']??'User'))?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">INVENTORY CONTROL</div><h1>Stocktakes</h1><p class="muted">Snapshot stock, capture physical counts, and apply reviewed variances with an audit trail.</p></div><form method="get"><label for="stocktake-school">School</label> <select id="stocktake-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$school?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></form></section><div id="stocktake-app" data-api="api/stocktakes.php" data-school="<?=$school?>" data-manager="<?=$manager?'1':'0'?>" data-csrf="<?=e(csrf_token())?>"><p class="muted" role="status">Loading stocktakes…</p></div><p><a class="button" href="operations.php?tab=stock&amp;school_id=<?=$school?>">Back to stock operations</a></p></div></main></div></body></html>

